import{_ as o,C as e,o as d,c as r,j as s,a as p,E as t,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·泰定","description":"坐忘论第六篇精读：定极生慧，慧而不用，恬智相养而归真常；由有意守定进入无心于定而无所不定。","frontmatter":{"title":"坐忘论·泰定","description":"坐忘论第六篇精读：定极生慧，慧而不用，恬智相养而归真常；由有意守定进入无心于定而无所不定。","category":"guide","aliases":["坐忘论泰定","泰定六","坐忘论精读之七"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-06.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-06.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/chapter-06.md"};function g(u,a,b,m,v,x){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),l=e("DaoKeywordCards");return d(),r("div",null,[a[0]||(a[0]=s("h1",{id:"坐忘论·泰定",tabindex:"-1"},[p("坐忘论·泰定 "),s("a",{class:"header-anchor",href:"#坐忘论·泰定","aria-label":'Permalink to "坐忘论·泰定"'},"​")],-1)),t(i,{title:"无心于定，而无所不定",summary:"本篇由具体调心进入成熟定境，也是全书理论最精微的部分。它最重要的不是「定能生慧」，而是慧生以后怎样不破坏定——司马承祯直言：非生慧难，慧而不用难。",points:[{label:"说定",text:"形如槁木，心若死灰；虚静至极，则道居而慧生。"},{label:"说慧",text:"慧出本性，非适今有；宝而怀之，勿以多知而伤于定。"},{label:"说养",text:"以恬养智、以智养恬，智与恬交相养，和理出于性。"}],hint:"可与《天隐子·神解》对读：那里的「信定闲慧」四解，正是这里「定慧交养」的更简说法。"}),a[1]||(a[1]=s("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),s("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=s("p",null,[s("strong",null,"一、泰定的定义及定极生慧")],-1)),t(n,{paragraphs:["夫定者，出俗之极地，致道之初基，习静之成功，持安之毕事。","形如槁木，心若死灰，无感无求，寂泊之至，无心于定，而无所不定，故曰泰定。","庄云：宇泰定者，发乎天光。宇则心也，天光则发慧也。","心为道之器宇，虚静至极，则道居而慧生，慧出本性，非适今有，故曰天光。","但以贪爱浊乱，遂至昏迷。澡雪柔挺，复归纯静，本真神识，稍稍自明，非谓今时别生他慧。"]}),a[3]||(a[3]=s("p",null,[s("strong",null,"二、慧生以后，最难的是不用")],-1)),t(n,{paragraphs:["慧既生已，宝而怀之，勿以多知而伤于定。","非生慧难，慧而不用难。自古忘形者众，忘名者寡。","慧而不用，是忘名也，天下希及之，故为难。","贵能不骄，富能不奢，为无俗过，故得长守富贵。定而不动，慧而不用，为无道过，故得深证真常。"]}),a[4]||(a[4]=s("p",null,[s("strong",null,"三、知道、言说与得道的区别")],-1)),t(n,{paragraphs:["庄云：知道易，而弗言难。知而不言，所以之天；知而言之，所以之人。","古之人天，而不人慧，能知道，非得道也。","人知得慧之利，未知得道之益。因慧以明至理，纵辩以感物情，兴心徇事，触类而长，自云处动而常寂，焉知寂者寂以待物乎。","此语俱非泰定也。智虽出众，弥不近道。本期逐鹿，获兔而归。所得太微，良由局小。"]}),a[5]||(a[5]=s("p",null,[s("strong",null,"四、以恬养智，以智养恬")],-1)),t(n,{paragraphs:["庄云：古之治道者，以恬养智。智生而无以智为也，谓之以智养恬。智与恬交相养，而和理出其性。","恬智则定慧也，和理则道德也。有智不用而安其恬，积而久之自成道德。"]}),a[6]||(a[6]=s("p",null,[s("strong",null,"五、泰定的形成与征验")],-1)),t(n,{paragraphs:["然论此定，因为而得成，或因观利而见害，惧祸而息心，捐舍涤除，积习心熟，同归于定，咸若自然。","疾雷破山而不惊，白刃交前而不惧，视名利如过隙，知生死如溃痈，故知用志不分，乃凝于神。","心之虚妙，不可思也。夫心之为物也，即体非有，随用非无，不驰而速，不召而至，怒则玄石饮羽，怨则朱夏殒霜，纵恶则九幽匪遥，积善则三清何远，忽来忽往，动寂不能名，时可时否，蓍龟莫能测，其为调御，岂鹿马比其难乎。"]}),a[7]||(a[7]=s("p",null,[s("strong",null,"六、总摄修法：渐修与顿证")],-1)),t(n,{paragraphs:["太上老君运常善以度人，升灵台而演妙，略三乘之因果，广万有之自然，渐之以日损有为，顿之以证归无学，喻则张弓凿矢，法则挫锐解纷，修之有常，习以成性，黜聪隳体，嗒然坐忘，不动于寂，几微入照。","履殊方者，了义无日，游斯道者，观妙可期，力少功多，要矣妙矣。"]}),a[8]||(a[8]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),t(l,{items:[{term:"出俗之极地",pinyin:["chū","sú","zhī","jí","dì"],meaning:"定是摆脱世俗爱恶、得失与躁竞所能达到的极深境地。非仅离开社会生活，而是心不再遵循世俗心的运行方式。"},{term:"致道之初基",pinyin:["zhì","dào","zhī","chū","jī"],meaning:"定又是达到大道的初步基础。与「出俗之极地」并观：从修心看定已极深，从证道看定仍只是基础。"},{term:"宇泰定",pinyin:["yǔ","tài","dìng"],meaning:"语本《庄子·庚桑楚》「宇泰定者，发乎天光」。本篇以「宇」为心之器宇：心虚而不受，便成为道所居之宇。"},{term:"天光",pinyin:["tiān","guāng"],meaning:"本性智慧自然显发。天，自然本有；光，照明辨别。非外在光象，也非静坐中所见亮光。"},{term:"宝而怀之",pinyin:["bǎo","ér","huái","zhī"],meaning:"慧生以后如珍藏宝物般含藏于心。怀，非拒绝一切必要运用，而是不急于宣说、炫耀、以慧换名。"},{term:"忘形",pinyin:["wàng","xíng"],meaning:"静坐中不觉身体、对身形得失较为淡泊、能忍受简朴。司马承祯说自古能一定程度忘形者并不少见。"},{term:"忘名",pinyin:["wàng","míng"],meaning:"不把修行所得变成新的自我资本（我是得定者、我是有慧者）。名相细微，常隐藏在修行成就之中，故比忘形更难。"},{term:"道过",pinyin:["dào","guò"],meaning:"修道过程中特有的过失：因定自高、因慧好辩、以境界分高下。俗过易识别，道过常披着修道外衣，故更难察觉。"},{term:"逐鹿获兔",pinyin:["zhú","lù","huò","tù"],meaning:"本欲逐鹿（得道、真常），却只捉到兔子（智慧、辩才、名声）。喻得少许慧解便满足，志向与心量太局促。"},{term:"恬智",pinyin:["tián","zhì"],meaning:"恬，恬静，本篇释为「定」；智，智慧，本篇释为「慧」。恬智交养即定慧交养，语本《庄子·缮性》。"},{term:"和理",pinyin:["hé","lǐ"],meaning:"心不偏于两端以后自然呈现的秩序。恬智达到和谐，合道之理便从本性中自然显现，本篇以之对应「道德」。"},{term:"即体非有，随用非无",pinyin:["jí","tǐ","fēi","yǒu","suí","yòng","fēi","wú"],meaning:"就体而言找不到固定可执的实体；就用而言却确实能感知、造业、生慧。故既不可执心为恒常实物，也不可落入断灭空无。"},{term:"玄石饮羽",pinyin:["xuán","shí","yǐn","yǔ"],meaning:"「饮羽」谓箭入极深至箭羽没入。用李广射石传说，说明心志能强烈影响身体力量与行为结果。"},{term:"朱夏殒霜",pinyin:["zhū","xià","yǔn","shuāng"],meaning:"朱夏，盛夏；殒霜，降霜。古代冤气感天之传说，属传统天人感应观，非现代气象因果。用以强调心念怨气力量巨大。"},{term:"九幽",pinyin:["jiǔ","yōu"],meaning:"道教幽冥、苦难境界的表达。既可指死后果报，也可从现世心性理解为恶念长期放纵所形成的幽暗心境。"},{term:"三清",pinyin:["sān","qīng"],meaning:"道教最高神圣境界（玉清、上清、太清）。「纵恶则九幽匪遥，积善则三清何远」两两相对。"},{term:"蓍龟",pinyin:["shī","guī"],meaning:"蓍草与龟甲，古代占卜之法。此处夸张说明心念幽微迅疾，难以把握预测。"},{term:"三乘",pinyin:["sān","chéng"],meaning:"佛教术语，通常指声闻、缘觉、菩萨三乘。唐代道教文献吸收并改造此类分类语言，「略三乘之因果」反映道佛交涉背景。"},{term:"无学",pinyin:["wú","xué"],meaning:"佛教术语，指修学完成、已无更高内容需学的果位。此处借以表达能所双忘、不再刻意守定、由有为之学归入自然无为。"},{term:"挫锐解纷",pinyin:["cuò","ruì","jiě","fēn"],meaning:"语本《道德经》「挫其锐，解其纷」。挫锐，不逞才不争胜不以慧炫耀；解纷，解除杂念、人事和名相纠缠。"},{term:"黜聪隳体",pinyin:["chù","cōng","huī","tǐ"],meaning:"黜聪，退去自作聪明与向外炫用的智巧；隳体，松开对形体与自我身份的固执。非消灭智慧，也非损伤身体。"},{term:"嗒然坐忘",pinyin:["tà","rán","zuò","wàng"],meaning:"嗒然，语本《庄子》，形容自我意识淡化、若有所丧的状态。所忘是身执、智执、名执与「我正在得定」的意识，而觉照未断。"},{term:"几微入照",pinyin:["jī","wēi","rù","zhào"],meaning:"几微，极细微的念头与变化征兆；照，清醒觉察。谓寂静更深而觉照更细，念头尚在萌芽已被察觉——「息乱而不灭照」的完成形态。"},{term:"修之有常",pinyin:["xiū","zhī","yǒu","cháng"],meaning:"修习必须持久而有常。不能依赖一时兴奋、一次深度体验或外界赞誉带来的动力，须落实为长期稳定不过度的训练。"},{term:"习以成性",pinyin:["xí","yǐ","chéng","xìng"],meaning:"长期练习使安定成为自然性情。凡夫的逐境亦由积习而成，故此「自然」并不等于顺从当前习惯。"}]}),a[9]||(a[9]=h("",181))])}const C=o(c,[["render",g]]);export{y as __pageData,C as default};
